2:# scoreboard.sh — Render a reviewer competition scoreboard.
6:usage() { echo "Usage: scoreboard.sh --tally-file FILE --reviewer-labels CSV --output-file FILE" >&2; }
14:        --reviewer-labels) LABELS="${2:?--reviewer-labels requires a value}"; shift 2 ;;
17:        *) echo "scoreboard.sh: unknown option: $1" >&2; usage; exit 2 ;;
21:[[ -n "$OUTPUT_FILE" ]] || { echo "scoreboard.sh: --output-file is required" >&2; exit 2; }
29:    for label in $LABELS; do
30:        label=$(printf '%s' "$label" | sed 's/^ *//; s/ *$//')
31:        [[ -n "$label" ]] || continue
34:            score=$(awk -v label="$label" '$0 ~ label && $0 ~ /ACCEPTED=true/ { n++ } END { print n + 0 }' "$TALLY_FILE")
36:        printf '| %s | %s |\n' "$label" "$score"

